import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet for a newcomer → 60 + 6 + 5 = 71 G");
    it.todo("plain staff for a newcomer → 80 + 8 + 5 = 93 G");
    it.todo("plain potion for a newcomer → 40 + 4 + 5 = 49 G");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium (55 + 5 = 60 G for a newcomer)");
    it.todo("3 runes → 60 G base premium, block applies (66 + 5 = 71 G)");
    it.todo("4 runes → 100 G base premium, no block (110 + 5 = 115 G)");
    it.todo("7 runes → 175 G base premium (192.5 + 5 = 197.5 → 198 G, rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block across types (82.5 + 5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (132 + 5 = 137 G)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed steel sword, enchantment 3 → 165 G");
    it.todo("cursed surcharge applies only to the cursed item: cursed sword + plain amulet → 160 + 50 = 210 base, +16 first insurance +5 fee = 231 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (115 G for a newcomer)");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 + 30 + 10 + 5 = 145 G)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 + 10 + 5 = 195 G)");
    it.todo("customer with exactly 2 years → loyalty discount applies (100 − 20 + 10 + 5 = 95 G)");
    it.todo("customer with 1 year → no loyalty discount (115 G)");
    it.todo("second quote in a scenario gets the 15 % follow-up discount (first 115 G, second 100 G)");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular steel sword, enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune (no enchantment/material), damage 200 G → payout 100 G");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("damage below the deductible pays nothing (sword damage 50 G → payout 0)");
    it.todo("payout calculation of 350.5 G is rounded down to 350 G (enchantment 9 sword, damage 901 G)");
    it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
  });

  describe("claim — cap", () => {
    it.todo("remainingCap for a single sword is 2000 minus payout (damage 500 → payout 400, remainingCap 1600)");
    it.todo("sword + amulet → cap 3200 G (damage 500 on sword → remainingCap 2800)");
    it.todo("cursed sword → cap 2000 G, based on unmodified insurance value (damage 500 → remainingCap 1600)");
    it.todo("sword + 3 runes (a block) → insurance sum 1750, cap 3500 (damage 500 on sword → remainingCap 3100)");
    it.todo("two swords → cap 4000; two sword damages are separate, each with its own deductible");
    it.todo("two successive claims of 1500 G on a sword → payouts 1400 then 600, remainingCap 600 then 0");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (broomstick) throws");
    it.todo("claim for an item not in the policy (amulet when only a sword is insured) throws");
    it.todo("claim for an unknown item type throws");
    it.todo("claim with a negative damage amount (-200) throws");
    it.todo("claim with more damages of a type than insured (two swords, one insured) throws");
  });

  describe("CLI", () => {
    it.todo("reads the schema example from stdin and writes {results: [{premium}, {payout, remainingCap}]} to stdout");
    it.todo("exits non-zero and writes to stderr with no results on stdout for an unknown item type");
    it.todo("exits non-zero and writes to stderr for an invalid claim (negative amount)");
  });
});

