type Item = { type: string };
type QuoteStep = { op: "quote"; items: Item[] };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: unknown[];
};

export type ScenarioResult = { results: object[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const PROCESSING_FEE = 5;
// A block of 3 alike components costs 60 G instead of 3 × 25 = 75 G
const RUNE_BLOCK_DISCOUNT = 15;

// 10% surcharge, computed by division to stay in exact integer arithmetic
const firstInsuranceSurcharge = (basePremium: number): number => basePremium / 10;

// Only the final premium is rounded, always in MHPCO's favor
const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);

const runeBlockDiscount = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  return runeCount === 3 ? RUNE_BLOCK_DISCOUNT : 0;
};

const totalBasePremium = (items: Item[]): number => {
  const itemPremiums = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  return itemPremiums - runeBlockDiscount(items);
};

const quotePremium = (step: QuoteStep): number => {
  const basePremium = totalBasePremium(step.items);
  return roundInMHPCOsFavor(basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(step) }] };
};

