  const basePremium = totalBasePremium(step.items);
  return roundInMHPCOsFavor(
    basePremium +
      curseSurcharge(step.items) +
      firstInsuranceSurcharge(basePremium) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(step) }] };
};

