content.content:
// A block of 3 alike components costs 60 G instead of 3 × 25 = 75 G
const BLOCK_DISCOUNT = 15;

// 10% surcharge, computed by division to stay in exact integer arithmetic
const firstInsuranceSurcharge = (policyBasePremium: number): number => policyBasePremium / 10;

// 20% discount for customers with MHPCO for at least 2 years, computed by division
const loyaltyDiscount = (policyBasePremium: number, yearsWithMHPCO: number): number =>
  yearsWithMHPCO >= 2 ? policyBasePremium / 5 : 0;

// Only the final premium is rounded, always in MHPCO's favor
const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);

const blockDiscountFor = (items: Item[], type: string): number => {
  const count = items.filter((item) => item.type === type).length;
  return count === 3 ? BLOCK_DISCOUNT : 0;
};

const componentBlockDiscounts = (items: Item[]): number =>
  blockDiscountFor(items, "rune") + blockDiscountFor(items, "moonstone");

  perItemSurcharge(items, (item) => item.cursed === true, (premium) => premium / 2);

// 30% of each highly enchanted item's own base premium
const highEnchantmentSurcharge = (items: Item[]): number =>
  perItemSurcharge(items, (item) => (item.enchantment ?? 0) >= 5, (premium) => (premium * 3) / 10);

const quotePremium = (step: QuoteStep, yearsWithMHPCO: number): number => {
  const policyBasePremium = totalBasePremium(step.items);
  return roundInMHPCOsFavor(
    policyBasePremium +
      curseSurcharge(step.items) +
      highEnchantmentSurcharge(step.items) +
      firstInsuranceSurcharge(policyBasePremium) -
      loyaltyDiscount(policyBasePremium, yearsWithMHPCO) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(step, scenario.customer.yearsWithMHPCO) }] };
};

