type Item = { type: string; cursed?: boolean; enchantment?: number };
type QuoteStep = { op: "quote"; items: Item[] };
type Damage = { itemType: string; amount: number };
type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: unknown[];
};

export type ScenarioResult = { results: object[] };

// MHPCO price list: insurance value and base premium per item type
const PRICE_LIST: Record<string, { insuranceValue: number; basePremium: number }> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: { insuranceValue: 250, basePremium: 25 },
  moonstone: { insuranceValue: 250, basePremium: 25 },
};

const PROCESSING_FEE = 5;
// A block of 3 alike components costs 60 G instead of 3 × 25 = 75 G
const BLOCK_DISCOUNT = 15;

// 10% surcharge, computed by division to stay in exact integer arithmetic
const firstInsuranceSurcharge = (policyBasePremium: number): number => policyBasePremium / 10;

// 20% discount for customers with MHPCO for at least 2 years, computed by division
   32:21  error  No magic number: 2    no-magic-numbers
   32:45  error  No magic number: 5    no-magic-numbers
   36:45  error  No magic number: 15   no-magic-numbers
   36:51  error  No magic number: 100  no-magic-numbers
   45:20  error  No magic number: 3    no-magic-numbers
   68:82  error  No magic number: 2    no-magic-numbers
   72:64  error  No magic number: 5    no-magic-numbers
   72:91  error  No magic number: 3    no-magic-numbers
